const treeCellInfo = tree.getCellAt(event.clientX, event.clientY);
if (treeCellInfo.row == -1) {
  return;
}

if (treeCellInfo.col.id == "selectCol") {
  HandleSelectColClick(event, treeCellInfo.row);
  return;
}

if (treeCellInfo.col.id == "deleteCol") {
